    public static string GetPathData(string iconKey) => iconKey switch
    {
        "cursor" => Cursor,
        "move" => Move,
        "pan" => Pan,
        "ruler" or "dimension" => Ruler,
        "scale" => Resize,
        "mirror" or "flip-horizontal" => FlipHorizontal,
        "flip-vertical" => FlipVertical,
        "duplicate" => Copy,
        "offset" => Offset,
        "thickness" => Thickness,
        "cleanup" => Sparkle,
        "pattern" => Grid,
        "fold" => PaperFolding,
        "sewing" => Sewing,
        "trim" => Cut,
        "fillet" => Fillet,
        "chamfer" => Chamfer,
        "convert-lines" => LineStyle,
        "line" => Line,
        "rectangle" => Rectangle,
        "circle" => Circle,
        "text" => Text,
        "pen" => Pen,
        "polygon" => Polygon,
